const bronzeDeviceSheet=new Image();bronzeDeviceSheet.assetSrc='assets/bronze-device-v2.png';
const BRONZE_SWEEPS=[{start:1.2,end:2.2,from:-Math.PI/4,to:Math.PI/4},{start:2.6,end:3.8,from:Math.PI/4,to:-Math.PI/2}];
function beginBronzeDevice(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'bronzeReverseRay',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},angle:Math.atan2(p.y-e.y,p.x-e.x),hits:[false,false]};}
function bronzeBeamAngle(s,time){return s.from+(s.to-s.from)*Math.max(0,Math.min(1,(time-s.start)/(s.end-s.start)));}
function bronzeBeamContact(a,point,from,to){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,r=Math.hypot(dx,dy);if(r<70-1e-8||r>420+1e-8)return false;let theta=Math.atan2(dy,dx)-a.angle;theta=Math.atan2(Math.sin(theta),Math.cos(theta));let half=Math.asin(Math.min(1,18/r)),low=Math.min(from,to)-half,high=Math.max(from,to)+half;return [-Math.PI*2,0,Math.PI*2].some(turn=>theta+turn>=low-1e-8&&theta+turn<=high+1e-8);}
const bronzeDeviceAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e1')return bronzeDeviceAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='bronzeReverseRay'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=380&&clear){beginBronzeDevice(e);return;}e.state='idle';if(d>800&&!e.aware||d<=220&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,70*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 for(let [i,s]of BRONZE_SWEEPS.entries()){if(dead||a.hits[i]||e.elapsed<s.start||before>=s.end)continue;let from=bronzeBeamAngle(s,Math.max(before,s.start)),to=bronzeBeamAngle(s,Math.min(e.elapsed,s.end));if(bronzeBeamContact(a,p,from,to)&&lineClear(a.origin,p)){a.hits[i]=true;e.struck=true;hurt(52);playSound('impact',p.x,p.y);}}
 if(e.elapsed>=2.2&&e.elapsed<2.6){a.windup=2.6;e.struck=false;}if(e.elapsed>=4.8){e.attack=null;e.state='idle';e.t=3;}
};
const bronzeDeviceDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e1'||!bronzeDeviceSheet.complete||!bronzeDeviceSheet.naturalWidth||!bronzeDeviceSheet.naturalHeight)return bronzeDeviceDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='bronzeReverseRay')f={row:2,col:e.elapsed<.7?0:e.elapsed<1.2||e.elapsed>=2.2&&e.elapsed<2.6?1:e.elapsed<3.8?2:3};let q=project(e.x,e.y),sw=bronzeDeviceSheet.naturalWidth/4,sh=bronzeDeviceSheet.naturalHeight/3,w=220,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y-12);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,bronzeDeviceSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.87,w,h);else ctx.drawImage(bronzeDeviceSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.87,w,h);ctx.restore();return true;};
const bronzeDeviceSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e1'?175:bronzeDeviceSizeBase(e);
function drawBronzeBeam(a,offset,active){let angle=a.angle+offset,end=0,previous=a.origin;for(let r=6;r<=420;r+=6){let q={x:a.origin.x+Math.cos(angle)*r,y:a.origin.y+Math.sin(angle)*r};if(!passable(q.x,q.y,0)||!lineClear(previous,q))break;end=r;previous=q;}if(end<70)return;let near=Math.asin(18/70),far=Math.asin(18/end),q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.rotate(angle);ctx.fillStyle=active?'#75ddec66':'#d1b57822';ctx.strokeStyle=active?'#d8fcff':'#d8bb80';ctx.lineWidth=active?2:1;ctx.beginPath();ctx.moveTo(70*Math.cos(near),-18);ctx.lineTo(end*Math.cos(far),-18);ctx.arc(0,0,end,-far,far);ctx.lineTo(70*Math.cos(near),18);ctx.arc(0,0,70,near,-near,true);ctx.closePath();ctx.fill();ctx.stroke();if(active){ctx.strokeStyle='#f2ffff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(70,0);ctx.lineTo(end,0);ctx.stroke();}ctx.restore();}
const bronzeDeviceGroundBase=drawGroundEffects;drawGroundEffects=()=>{bronzeDeviceGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e1'):enemies)){let a=e.attack;if(e.species!=='r9e1'||e.hp<=0||a?.pattern!=='bronzeReverseRay'||!visibleAt(e.x,e.y))continue;if(e.elapsed>=3.8){groundRing(e.x,e.y,35,'#a5d8c5',1);continue;}let s=BRONZE_SWEEPS[e.elapsed>=2.2?1:0],active=e.elapsed>=s.start&&e.elapsed<=s.end,angle=bronzeBeamAngle(s,e.elapsed);drawBronzeBeam(a,angle,active);groundRing(e.x,e.y,70,'#90b7b3',1);let q=project(e.x,e.y),dir=Math.sign(s.to-s.from),end=a.angle+s.to;ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.strokeStyle=e.elapsed>=2.2?'#efd39e':'#95becb';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,130,a.angle+angle,end,dir<0);ctx.stroke();ctx.translate(Math.cos(end)*130,Math.sin(end)*130);ctx.rotate(end+dir*Math.PI/2);ctx.beginPath();ctx.moveTo(-9,-6);ctx.lineTo(0,0);ctx.lineTo(-9,6);ctx.stroke();ctx.restore();}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r9e1',animateEnemy,drawRegionEnemy);
